    const t = designTaxon(design);
    if (!t) return { in_scope: false, reason: `scoped to ${taxa.join(', ')}${sc.basis ? ' (' + sc.basis + ')' : ''}; the design names no taxon, so this row is not judged. Pass taxon to judge it.`, scope: sc };
